'use strict';

// MODULES //

var isnan = require( '@stdlib/assert/is-nan' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var snansumpw = require( '@stdlib/blas/ext/base/snansumpw' ).ndarray;


// MAIN //

/**
* Computes the arithmetic mean of a single-precision floating-point strided array, ignoring `NaN` values and using pairwise summation.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Float32Array} x - input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {number} arithmetic mean
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 2.0, 1.0, 2.0, -2.0, -2.0, 2.0, 3.0, 4.0, NaN, NaN ] );
*
* var v = snanmeanpw( 5, x, 2, 1 );
* // returns 1.25
*/
function snanmeanpw( N, x, strideX, offsetX ) {
	var ix;
	var n;
	var i;
	var v;

	if ( N <= 0 ) {
		return NaN;
	}

	if ( N === 1 || strideX === 0 ) {
		return x[ offsetX ];
	}

	ix = offsetX;
	n = 0;

	// Count non-NaN elements
	for ( i = 0; i < N; i++ ) {
		v = x[ ix ];
		if ( !isnan( v ) ) {
			n += 1;
		}
		ix += strideX;
	}

	if ( n === 0 ) {
		return NaN;
	}

	return float64ToFloat32( snansumpw( N, x, strideX, offsetX ) / n );
}


// EXPORTS //

module.exports = snanmeanpw;
